teleton:
  sucursales-captacion: ["0519", "4899", "1037", "1905"]
  pivote-anio-tarjeta: 49            # AA > 49 es 19AA; AA <= 49 es 20AA

// ---------------------------------------------------------------------------
int validaSucursalYVigencia(PantallaQ050066 p, CabeceraComs h, YearMonth mesLinea) {
    if (!s080.datosSucursal(h.sucursal()).ok()) return 26;
    if (props.validarSucursalCaptacion()
            && !props.sucursalesCaptacion().contains(h.sucursal())) return 63;

    if (!p.cuentaNumerica()) return 1;
    int error = tarjetas.valida(p.tarjeta());                 // 70063000 + 70064000
    if (error != 0) return error;

    if (!p.anioVtoNumerico() || p.mesVto() < 1 || p.mesVto() > 12) return 36;
    int siglo = (p.anioVto() > props.pivoteAnioTarjeta()) ? 1900 : 2000;
    YearMonth vence = YearMonth.of(siglo + p.anioVto(), p.mesVto());
    if (vence.isBefore(mesLinea)) return 37;                  // WKS-SSAAMM-TARJ < WKS-SSAAMM-LINEA

    // El CVV de la pantalla NO se conserva (ver riesgo): la validación está comentada en el fuente
    return 0;
}

@Component
@RequiredArgsConstructor
public class TarjetaValidator {

    private final BinRepository bines;            // S500B04TBINES
    private final TablaBinesMemoria tablaBines;   // WKS-BIN-NUM (hasta 1000 renglones)

    /** 70063000: pesos 2,1,2,1... de izquierda a derecha sobre 16 dígitos con ceros a la izquierda. */
    static boolean luhnValido(String tarjeta16) {
        int suma = 0;
        for (int i = 0; i < 15; i++) {
            int p = (tarjeta16.charAt(i) - '0') * ((i % 2 == 0) ? 2 : 1);
            suma += p / 10 + p % 10;                   // WKS-DG1-PESO + WKS-DG2-PESO
        }
        int digito = (10 - suma % 10) % 10;            // PIC 9 trunca el 10 a 0; aquí se hace explícito
        return digito == tarjeta16.charAt(15) - '0';
    }

    /** 70064000: BIN de 6 dígitos tras los ceros de relleno y clave contable por emisor. */
    ResultadoBin claveDonativo(String tarjeta16) {
        String sinRelleno = tarjeta16.replaceFirst("^0{0,3}", "");
        int bin = Integer.parseInt(sinRelleno.substring(0, 6));
        if (Set.of(34, 35, 37).contains(bin / 10_000)) {
            return ResultadoBin.amex(796, 97);            // W88-BIN-02-AMEX
        }
        return tablaBines.busca(bin)
                .or(() -> bines.findById(bin).map(b -> b.validoTeleton() ? b : null))
                .map(b -> ResultadoBin.nacional(b.emisor() == 2 ? 793 : 794, b.emisor(), b.negocio()))
                .orElseGet(() -> bines.existsById(bin)
                        ? ResultadoBin.error(29)              // BIN no válido para TELETON
                        : ResultadoBin.internacional(795));   // NOTFOUND: tarjeta internacional
    }
}

/** 50030490: S041 con opción A debajo del umbral de supervisor y B a partir de él. */
long seguridadOperador(BigDecimal importe, String pantalla, Globales g) {
    char opcion = importe.compareTo(g.importeSupervisor()) < 0 ? 'A' : 'B';
    ResultadoS041 r = s041.valida(pantalla, opcion);
    return switch (r.resultado()) {
        case 0  -> r.nominaGeneral();
        case 1  -> r.nominaFuncionario();
        default -> throw new RechazoDonativo(r.codigoError());
    };
}

/** 50030700: B24 solo se consulta en estos casos; el resto se aplica sin autorización. */
boolean requiereAutorizacionB24(ResultadoBin bin, BigDecimal importe, Globales g) {
    if (!estado.b24Habilitado()) return false;            // HI 36: W88-SIN-S036
    return bin.bin() == props.binAutorizacionObligatoria() // 602089, compilado en el fuente
        || bin.internacional()
        || importe.compareTo(g.importeAutorizacion()) >= 0; // B00T-IMP-AUTORI
}

@Service
@RequiredArgsConstructor
public class DonativoSucursalService {

    private final GlobalesRepository globales;     // S500B00TGLOBAL
    private final DonativoRepository movtos;       // S500B02TMOVTOS
    private final RegistroContableS151 s151;       // L002 REGISTRAS
    private final JournalRecuperacion journal;     // I02-LOG

    @Transactional
    public Donativo abona(SolicitudDonativo s, ResultadoBin bin) {
        int estatus = bin.amex() ? 15 : 0;
        int clave   = bin.amex() ? 796 : bin.claveTransaccion();

        // 99901-LOCK + ADD 1 TO B00T-NUM-AUTORIZ: folio con bloqueo pesimista en lugar de reintento por GO TO
        long folio = globales.siguienteAutorizacion();            // @Lock(PESSIMISTIC_WRITE)
        String autorizacion = "55" + "%010d".formatted(folio);    // WKS-PREFJ-TRANS = 55

        var d = Donativo.builder()
                .autorizacion(autorizacion)
                .sucursal(s.sucursal()).caja(s.caja()).nomina(s.nomina())
                .tarjeta(Pan.tokeniza(s.tarjeta()))                // nunca el PAN en claro
                .claveMovimiento(clave).estatus(estatus)
                .importe(s.importe().setScale(2, RoundingMode.UNNECESSARY))
                .vencimiento(s.vencimiento())
                .emisor(bin.emisor()).negocio(bin.negocio())
                .autS151(s151.registra(s, clave))                  // 50030900-ENV-S151-50066
                .autB24(s.autB24()).nodoB24(props.nodoDestino())
                .build();                                          // B02T-CVV no se migra
        journal.registra(d);                                        // 70030000-GRABA-LOG
        return movtos.save(d);                                      // 70040000-GRABA-BASE
    }
}
